let DEVICE = "YOUR_DEVICE_ID";
let TOPIC_CMD = "devices/" + DEVICE + "/command";    // phone -> device (retain=false)
let TOPIC_CFG = "devices/" + DEVICE + "/config";     // phone -> device (retain=true)
let TOPIC_HB = "devices/" + DEVICE + "/heartbeat";   // device -> phone (retain=true, "last seen")
let TOPIC_ALIVE = "mon/" + DEVICE + "/alive";        // device -> monitor (retain=false), absolute (outside topic_prefix)
let STALE_SEC = 120;
let WATCHDOG_WIFI_SEC = 900;     // reboot if Wi-Fi down this long (recover wedged net stack)
let WATCHDOG_MQTT_SEC = 10800;   // reboot if broker unreachable this long while Wi-Fi is up
let RESET_REASON_SW = 3;         // ESP_RST_SW — resume the timer ONLY on this (1=power-on => OFF)
let sw_on = false;
let remain = 0;
let mode = "";
let last_ack = "";
let ntp_synced = false;
let cfg_v = 0;
let cfg_sch = 0;
let cfg_h = 6;
let cfg_m = 0;
let cfg_dur = 90;
let cfg_max = 180;
let boot_rt_on = 0;
let boot_rt_remain = 0;
let boot_rt_mode = "";
let hb_last_ts = 0;
let hb_elapsed = 0;
let mqtt_init_done = false;
let hb_pending = false;
let wifi_down_sec = 0;
let mqtt_down_sec = 0;
let script_switching = false;
function get_unixtime() {
let s = Shelly.getComponentStatus("sys");
if (s) return s.unixtime;
return 0;
}
function get_query_param(qs, name) {
if (typeof qs !== "string" || qs.length === 0) return "";
let search = name + "=";
let idx = qs.indexOf(search);
if (idx < 0) return "";
let start = idx + search.length;
let end = qs.indexOf("&", start);
if (end < 0) end = qs.length;
return qs.slice(start, end);
}
function persist_rt() {
kvs_save("rt", JSON.stringify({ on: sw_on ? 1 : 0, r: remain, m: mode }));
}
function clear_rt() {
kvs_save("rt", JSON.stringify({ on: 0, r: 0, m: "" }));
}
function turn_on(duration_min, new_mode) {
if (duration_min > cfg_max) duration_min = cfg_max;
remain = duration_min * 60;
mode = new_mode;
sw_on = true;
script_switching = true;
Shelly.call("Switch.Set", {id: 0, on: true}, function() {
script_switching = false;
});
persist_rt();
}
function turn_off() {
remain = 0;
mode = "";
sw_on = false;
script_switching = true;
Shelly.call("Switch.Set", {id: 0, on: false}, function() {
script_switching = false;
});
persist_rt();
}
function execute_command(cmd) {
if (cmd === "on") {
turn_on(cfg_dur, "remote");
} else if (cmd === "t90") {
turn_on(90, "remote");
} else if (cmd === "off") {
if (sw_on) turn_off();
} else if (cmd === "ext") {
if (sw_on) {
let nr = remain + 30 * 60;
let mr = cfg_max * 60;
if (nr > mr) nr = mr;
remain = nr;
persist_rt();
} else {
turn_on(30, "remote");
}
} else if (cmd === "sub") {
if (sw_on) {
remain = remain - 30 * 60;
if (remain <= 0) {
turn_off();
} else {
persist_rt();
}
}
}
}
function do_publish_heartbeat(force) {
if (!ntp_synced) return;
let now = get_unixtime();
if (!force && now - hb_last_ts < 2) {
hb_pending = true;
return;
}
hb_pending = false;
hb_last_ts = now;
let st = "off";
if (sw_on) st = "on";
let hb = JSON.stringify({
s: st,
r: Math.floor(remain / 60),
mode: mode,
sch: cfg_sch,
h: cfg_h,
m: cfg_m,
v: cfg_v,
dur: cfg_dur,
max: cfg_max,
ack: last_ack,
ts: now,
ntp: true
});
MQTT.publish(TOPIC_HB, hb, 1, true);
hb_elapsed = 0;
}
function publish_heartbeat() {
do_publish_heartbeat(false);
}
function publish_alive() {
MQTT.publish(TOPIC_ALIVE, "1", 0, false);
}
function on_mqtt_command(topic, message) {
let msg = JSON.parse(message);
if (typeof msg !== "object" || msg === null) return;
if (!ntp_synced) return;
let now = get_unixtime();
if (typeof msg.ts !== "number") return;
let delta = now - msg.ts;
if (delta < 0) delta = -delta;
if (delta > STALE_SEC) return;
if (typeof msg.c !== "string") return;
execute_command(msg.c);
last_ack = msg.c;
publish_heartbeat();
}
let save_queue = [];
let saving = false;
function save_next() {
if (save_queue.length === 0) {
saving = false;
return;
}
saving = true;
let item = save_queue[0];
let nq = [];
let i = 1;
while (i < save_queue.length) {
nq.push(save_queue[i]);
i = i + 1;
}
save_queue = nq;
Shelly.call("KVS.Set", {key: item.k, value: item.v}, function() {
save_next();
});
}
function kvs_save(key, val) {
save_queue.push({k: key, v: val});
if (!saving) save_next();
}
function on_mqtt_config(topic, message) {
let msg = JSON.parse(message);
if (typeof msg !== "object" || msg === null) return;
if (typeof msg.v !== "number") return;
if (msg.v <= cfg_v) return;
cfg_v = msg.v;
if (typeof msg.sch === "number") cfg_sch = msg.sch;
if (typeof msg.h === "number") cfg_h = msg.h;
if (typeof msg.m === "number") cfg_m = msg.m;
if (typeof msg.dur === "number") cfg_dur = msg.dur;
if (typeof msg.max === "number") cfg_max = msg.max;
kvs_save("cfg_v", cfg_v);
kvs_save("cfg_sch", cfg_sch);
kvs_save("cfg_h", cfg_h);
kvs_save("cfg_m", cfg_m);
kvs_save("cfg_dur", cfg_dur);
kvs_save("cfg_max", cfg_max);
if (sw_on && remain > cfg_max * 60) {
remain = cfg_max * 60;
persist_rt();
}
publish_heartbeat();
}
function on_mqtt_connect() {
do_publish_heartbeat(true);
}
let tick_counter = 0;
function main_loop() {
tick_counter = tick_counter + 1;
if (tick_counter >= 2) {
tick_counter = 0;
publish_alive();
if (sw_on) {
remain = remain - 60;
if (remain < 0) remain = 0;
persist_rt(); // periodic persist (only while ON -> bounded flash wear)
if (remain <= 0) {
turn_off();
publish_heartbeat();
}
}
}
hb_elapsed = hb_elapsed + 30;
let hb_interval = 900;
if (sw_on) hb_interval = 300;
if (hb_pending || hb_elapsed >= hb_interval) {
do_publish_heartbeat(false);
}
if (cfg_sch === 1 && ntp_synced && !sw_on) {
let d = new Date();
let h = d.getHours();
let m = d.getMinutes();
if (h === cfg_h && m === cfg_m) {
cfg_sch = 0;
kvs_save("cfg_sch", 0);
turn_on(cfg_dur, "sch");
publish_heartbeat();
}
}
let wf = Shelly.getComponentStatus("wifi");
let wifi_up = (wf && (wf.status === "got ip" || wf.status === "connected"));
if (wifi_up) {
wifi_down_sec = 0;
} else {
wifi_down_sec = wifi_down_sec + 30;
}
let mq = Shelly.getComponentStatus("mqtt");
let mqtt_up = (mq && mq.connected === true);
if (mqtt_up) {
mqtt_down_sec = 0;
} else {
mqtt_down_sec = mqtt_down_sec + 30;
}
let do_reboot = false;
if (wifi_down_sec >= WATCHDOG_WIFI_SEC) do_reboot = true;
if (wifi_up && mqtt_down_sec >= WATCHDOG_MQTT_SEC) do_reboot = true;
if (do_reboot) {
Shelly.call("Shelly.Reboot", {});
}
if (!mqtt_init_done) {
mqtt_init_done = true;
let mqtt = Shelly.getComponentStatus("mqtt");
if (mqtt && mqtt.connected === true) {
on_mqtt_connect();
}
}
}
function boot_complete() {
let resume = false;
let sys0 = Shelly.getComponentStatus("sys");
let reason = (sys0 && typeof sys0.reset_reason === "number") ? sys0.reset_reason : -1;
if (reason === RESET_REASON_SW && boot_rt_on === 1 && boot_rt_remain > 0) {
resume = true;
}
script_switching = true;
if (resume) {
remain = boot_rt_remain;
mode = boot_rt_mode;
sw_on = true;
Shelly.call("Switch.Set", {id: 0, on: true}, function() {
script_switching = false;
});
persist_rt();
} else {
remain = 0;
mode = "";
sw_on = false;
Shelly.call("Switch.Set", {id: 0, on: false}, function() {
script_switching = false;
});
clear_rt();
}
MQTT.subscribe(TOPIC_CMD, on_mqtt_command);
MQTT.subscribe(TOPIC_CFG, on_mqtt_config);
Timer.set(30000, true, main_loop);
Shelly.addStatusHandler(function(event) {
if (event.component === "sys") {
if (event.delta && typeof event.delta.unixtime === "number") {
if (event.delta.unixtime > 1700000000) {
ntp_synced = true;
}
}
}
if (event.component === "mqtt") {
if (event.delta && event.delta.connected === true) {
on_mqtt_connect();
}
}
if (event.component === "switch:0") {
if (event.delta && typeof event.delta.output !== "undefined") {
if (script_switching) return;
if (event.delta.output) {
remain = cfg_dur * 60;
mode = "manual";
sw_on = true;
} else {
remain = 0;
mode = "";
sw_on = false;
}
last_ack = "btn";
persist_rt();
publish_heartbeat();
}
}
});
HTTPServer.registerEndpoint("coffee_status", function(req, res) {
let ts = 0;
if (ntp_synced) ts = get_unixtime();
let st = "off";
if (sw_on) st = "on";
res.code = 200;
res.headers = [["Content-Type", "application/json"]];
res.body = JSON.stringify({
state: st,
remaining: Math.floor(remain / 60),
mode: mode,
sch: cfg_sch,
h: cfg_h,
m: cfg_m,
v: cfg_v,
dur: cfg_dur,
max: cfg_max,
ntp: ntp_synced,
ts: ts
});
res.send();
});
HTTPServer.registerEndpoint("coffee_command", function(req, res) {
let cmd = get_query_param(req.query, "cmd");
if (cmd === "") {
res.code = 400;
res.headers = [["Content-Type", "application/json"]];
res.body = JSON.stringify({ok: false, error: "missing cmd"});
res.send();
return;
}
if (cmd !== "on" && cmd !== "off" && cmd !== "ext" && cmd !== "sub" && cmd !== "t90") {
res.code = 400;
res.headers = [["Content-Type", "application/json"]];
res.body = JSON.stringify({ok: false, error: "unknown command"});
res.send();
return;
}
execute_command(cmd);
last_ack = cmd;
publish_heartbeat();
let st = "off";
if (sw_on) st = "on";
res.code = 200;
res.headers = [["Content-Type", "application/json"]];
res.body = JSON.stringify({
ok: true,
state: st,
remaining: Math.floor(remain / 60),
ack: cmd
});
res.send();
});
let sys = Shelly.getComponentStatus("sys");
if (sys && typeof sys.unixtime === "number" && sys.unixtime > 1700000000) {
ntp_synced = true;
}
print("Coffee timer v2 booted. resume:" + (resume ? "yes" : "no") + " NTP:" + (ntp_synced ? "yes" : "no"));
}
let kvs_keys = ["cfg_v", "cfg_sch", "cfg_h", "cfg_m", "cfg_dur", "cfg_max", "rt"];
let kvs_idx = 0;
function set_kvs_val(key, value) {
if (key === "cfg_v" && typeof value === "number") cfg_v = value;
if (key === "cfg_sch" && typeof value === "number") cfg_sch = value;
if (key === "cfg_h" && typeof value === "number") cfg_h = value;
if (key === "cfg_m" && typeof value === "number") cfg_m = value;
if (key === "cfg_dur" && typeof value === "number") cfg_dur = value;
if (key === "cfg_max" && typeof value === "number") cfg_max = value;
if (key === "rt" && typeof value === "string") {
let o = JSON.parse(value);
if (typeof o === "object" && o !== null) {
if (typeof o.on === "number") boot_rt_on = o.on;
if (typeof o.r === "number") boot_rt_remain = o.r;
if (typeof o.m === "string") boot_rt_mode = o.m;
}
}
}
function load_next_kvs() {
if (kvs_idx >= kvs_keys.length) {
boot_complete();
return;
}
let key = kvs_keys[kvs_idx];
kvs_idx = kvs_idx + 1;
Shelly.call("KVS.Get", {key: key}, function(res, err) {
let v = null;
if (res && typeof res.value !== "undefined") {
v = res.value;
}
set_kvs_val(key, v);
load_next_kvs();
});
}
load_next_kvs();
